// Lê TODOS os scores do Redis (nó "Redis Keys" com Get Values) e devolve 1 linha por palestrante,
// agrupado por macro tema e ranqueado dentro de cada tema. Saida = itens (1 por linha) pro Google Sheets.
const recs = [];
function pushParsed(v) {
  let r = v;
  if (typeof v === 'string') { try { r = JSON.parse(v); } catch (e) { return; } }
  if (r && r.id) recs.push(r);
}
for (const it of items) {
  const j = it.json || {};
  if (j.value !== undefined && (j.key || j.name)) pushParsed(j.value);
  else for (const [k, v] of Object.entries(j)) if (k.indexOf('pcur:pal:') === 0) pushParsed(v);
}

const byTema = {};
for (const r of recs) { const t = r.macro_tema || '18. OUTROS'; (byTema[t] = byTema[t] || []).push(r); }
const temas = Object.keys(byTema).sort((a, b) => (parseInt(a) || 999) - (parseInt(b) || 999));

const rows = [];
for (const t of temas) {
  const lst = byTema[t].slice().sort((a, b) => (b.pontuacao_total || 0) - (a.pontuacao_total || 0));
  lst.forEach((r, i) => {
    const n = r.notas || {};
    rows.push({ json: {
      macro_tema: t,
      rank: i + 1,
      nome: r.nome,
      pontuacao_total: r.pontuacao_total,
      compatibilidade_pct: r.compatibilidade,
      quem_e: n.quem_e, defende: n.defende, entrega: n.entrega,
      pra_quem: n.pra_quem, comprova: n.comprova, raiox: n.raiox,
      hubspot_id: String(r.id),
      wiki_url: r.wiki_url || '',
      atualizado_em: r.data_avaliacao || ''
    } });
  });
}
return rows.length ? rows : [{ json: { macro_tema: '', rank: '', nome: '(sem avaliados ainda)', pontuacao_total: '', compatibilidade_pct: '', quem_e: '', defende: '', entrega: '', pra_quem: '', comprova: '', raiox: '', hubspot_id: '', wiki_url: '', atualizado_em: '' } }];
